standalone.write_desktop:
write_desktop() {
  local executable="$LAB_ROOT/bin/omarchy-labctl"
  executable=${executable//\\/\\\\\\\\}
  executable=${executable//\"/\\\"}
  executable=${executable//\$/\\\$}
  executable=${executable//\`/\\\`}
  executable=${executable//%/%%}
  mkdir -p "$(dirname "$DESKTOP_FILE")"
  cat >"$DESKTOP_FILE" <<EOF
[Desktop Entry]
Name=Omarchy Lab
Comment=Disposable Omarchy KVM for development and PoCs
Exec="$executable" launch
Icon=omarchy
Terminal=false
Type=Application
Categories=System;Emulator;
EOF
  update-desktop-database "$(dirname "$DESKTOP_FILE")" 2>/dev/null || true
}
